80	        this.ownerMapper = ownerMapper;
81	        this.petMapper = petMapper;
82	        this.visitMapper = visitMapper;
83	    }
84	
85	    /**
86	     * Normalise a raw telephone number to E.164 form.
87	     *
88	     * <p>Spaces, dashes and brackets are stripped. A leading '+' and its country
89	     * code are kept when present; otherwise country code '+61' is assumed and a
90	     * single leading '0' is dropped from the national digits. The result must have
91	     * between 8 and 15 digits after the '+'.
92	     *
93	     * @return the E.164 string, or {@code null} if the input cannot form a valid one.
94	     */
95	    static String toE164(String raw) {
96	        if (raw == null) {
97	            return null;
98	        }
99	        String cleaned = raw.replaceAll("[\\s()\\[\\]-]", "");
100	        String digits;
101	        if (cleaned.startsWith("+")) {
102	            digits = cleaned.substring(1);
103	        } else {
104	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
105	            digits = "61" + national;
106	        }
107	        if (!digits.matches("[0-9]{8,15}")) {
108	            return null;
109	        }
110	        return "+" + digits;
111	    }
112	
113	    /**
114	     * Normalise a text field for case-insensitive, whitespace-insensitive identity
115	     * comparison: leading/trailing whitespace is trimmed, internal runs of whitespace
116	     * are collapsed to a single space, and the result is lower-cased. A {@code null}
117	     * input normalises to the empty string.
118	     */
119	    private static String normaliseIdentity(String value) {
120	        if (value == null) {
121	            return "";
122	        }
123	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
124	    }
125	
126	    /**
127	     * Build the customer code for a new owner as {@code '<LAST3>-<NNNN>'}, where LAST3 is the
128	     * upper-cased first three letters of the last name and NNNN is a global 4-digit zero-padded
129	     * sequence equal to one more than the current number of owners.
130	     */
131	    /**
132	     * Derive the stable, shared household identifier for owners sharing a household. It is a
133	     * deterministic UUID over the normalised last-name and address, so every owner in the same
134	     * household resolves to the same value regardless of the order in which they were created.
135	     */
136	    private static String householdId(String lastNameKey, String addressKey) {
137	        String seed = lastNameKey + "�" + addressKey;
138	        return UUID.nameUUIDFromBytes(seed.getBytes(StandardCharsets.UTF_8)).toString();
139	    }
